// ExportAuditReport is the resolver for the exportAuditReport field.
func (r *mutationResolver) ExportAuditReport(ctx context.Context, input types.ExportAuditReportInput) (*types.ExportAuditReportPayload, error) {
	// The report lists the audit's findings and the names of its auditors
	// and finding owners besides the audit.
	for _, action := range []string{
		probo.ActionFindingList,
		iam.ActionMembershipProfileList,
	} {
		if _, err := r.authorize(ctx, input.AuditID, action); err != nil {
			return nil, err
		}
	}

	scope, err := r.authorize(ctx, input.AuditID, probo.ActionAuditGet)
	if err != nil {
		return nil, err
	}

	workbook, err := r.probo.AuditPrivacy.Export(ctx, scope, input.AuditID)
	if err != nil {
		if errors.Is(err, coredata.ErrResourceNotFound) {
			return nil, gqlutils.NotFoundf(ctx, "audit not found")
		}

		r.logger.ErrorCtx(ctx, "cannot export audit report", log.Error(err))
		return nil, gqlutils.Internal(ctx)
	}

	return &types.ExportAuditReportPayload{
		Data: fmt.Sprintf("data:%s;base64,%s", xlsxexport.ContentType, base64.StdEncoding.EncodeToString(workbook)),
	}, nil
}
